"""SQLite Visible Agent Log: Append-only persistent ledger for background agent actions and metrics."""

from datetime import datetime
import json
from pathlib import Path
import sqlite3
import threading
from typing import List, Optional
from ..core.interfaces import BaseVisibleLogStore
from ..core.models import (
    AgentLogEntry,
    AgentSeverity,
    AgentType,
)


class SQLiteAgentLogStore(BaseVisibleLogStore):
    """Local SQLite engine managing visible audit logs generated by internal background agents."""

    def __init__(self, db_path: str = "./internal_agents.db"):
        self._db_path = db_path
        self._memory_conn: Optional[sqlite3.Connection] = None
        if db_path != ":memory:":
            Path(db_path).parent.mkdir(parents=True, exist_ok=True)
        else:
            self._memory_conn = sqlite3.connect(":memory:", check_same_thread=False)
            self._memory_conn.row_factory = sqlite3.Row

        self._lock = threading.Lock()
        self._init_db()

    def _get_connection(self) -> sqlite3.Connection:
        if self._memory_conn is not None:
            return self._memory_conn
        conn = sqlite3.connect(self._db_path, check_same_thread=False)
        conn.row_factory = sqlite3.Row
        return conn

    def _init_db(self) -> None:
        with self._lock:
            conn = self._get_connection()
            conn.execute("""
                CREATE TABLE IF NOT EXISTS internal_agent_logs (
                    id TEXT PRIMARY KEY,
                    agent_type TEXT NOT NULL,
                    severity TEXT NOT NULL,
                    action TEXT NOT NULL,
                    message TEXT NOT NULL,
                    metadata TEXT NOT NULL,
                    timestamp TEXT NOT NULL
                );
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_agent_logs_type
                ON internal_agent_logs(agent_type);
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_agent_logs_time
                ON internal_agent_logs(timestamp DESC);
            """)
            conn.execute("""
                CREATE TABLE IF NOT EXISTS internal_agent_schedules (
                    agent_type TEXT PRIMARY KEY,
                    interval_seconds REAL NOT NULL,
                    last_run_at TEXT,
                    next_run_at TEXT,
                    enabled INTEGER NOT NULL DEFAULT 1,
                    total_runs INTEGER NOT NULL DEFAULT 0,
                    last_status TEXT
                );
            """)
            conn.commit()
            if self._memory_conn is None:
                conn.close()

    def append_log(self, entry: AgentLogEntry) -> None:
        with self._lock:
            conn = self._get_connection()
            try:
                conn.execute(
                    """
                    INSERT INTO internal_agent_logs (
                        id, agent_type, severity, action, message, metadata, timestamp
                    ) VALUES (?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        entry.id,
                        entry.agent_type.value,
                        entry.severity.value,
                        entry.action,
                        entry.message,
                        json.dumps(entry.metadata),
                        entry.timestamp.isoformat(),
                    ),
                )
                conn.commit()
            finally:
                if self._memory_conn is None:
                    conn.close()

    def query_logs(
        self, agent_type: Optional[AgentType] = None, limit: int = 50
    ) -> List[AgentLogEntry]:
        query = "SELECT * FROM internal_agent_logs"
        params: list = []
        if agent_type:
            query += " WHERE agent_type = ?"
            params.append(agent_type.value)
        query += " ORDER BY timestamp DESC LIMIT ?"
        params.append(limit)

        with self._lock:
            conn = self._get_connection()
            try:
                cur = conn.execute(query, params)
                rows = cur.fetchall()
                entries = []
                for r in rows:
                    entries.append(
                        AgentLogEntry(
                            id=r["id"],
                            agent_type=AgentType(r["agent_type"]),
                            severity=AgentSeverity(r["severity"]),
                            action=r["action"],
                            message=r["message"],
                            metadata=json.loads(r["metadata"]),
                            timestamp=datetime.fromisoformat(r["timestamp"]),
                        )
                    )
                return entries
            finally:
                if self._memory_conn is None:
                    conn.close()

    def save_schedule(
        self,
        agent_type: str,
        interval_seconds: float,
        enabled: bool = True,
        last_run_at: Optional[str] = None,
        next_run_at: Optional[str] = None,
        last_status: Optional[str] = None,
    ) -> None:
        """Persist or update background schedule for an agent."""
        with self._lock:
            conn = self._get_connection()
            try:
                conn.execute(
                    """
                    INSERT INTO internal_agent_schedules (
                        agent_type, interval_seconds, last_run_at, next_run_at, enabled, last_status
                    ) VALUES (?, ?, ?, ?, ?, ?)
                    ON CONFLICT(agent_type) DO UPDATE SET
                        interval_seconds = excluded.interval_seconds,
                        enabled = excluded.enabled,
                        next_run_at = coalesce(excluded.next_run_at, internal_agent_schedules.next_run_at)
                    """,
                    (
                        agent_type,
                        interval_seconds,
                        last_run_at,
                        next_run_at,
                        1 if enabled else 0,
                        last_status,
                    ),
                )
                conn.commit()
            finally:
                if self._memory_conn is None:
                    conn.close()

    def get_schedules(self) -> List[dict]:
        """Fetch all persistent schedules across internal agents."""
        with self._lock:
            conn = self._get_connection()
            try:
                cur = conn.execute("SELECT * FROM internal_agent_schedules")
                rows = cur.fetchall()
                results = []
                for r in rows:
                    results.append({
                        "agent_type": r["agent_type"],
                        "interval_seconds": float(r["interval_seconds"]),
                        "last_run_at": r["last_run_at"],
                        "next_run_at": r["next_run_at"],
                        "enabled": bool(r["enabled"]),
                        "total_runs": int(r["total_runs"]),
                        "last_status": r["last_status"],
                    })
                return results
            finally:
                if self._memory_conn is None:
                    conn.close()

    def record_agent_run(
        self,
        agent_type: str,
        status: str,
        next_run_at: Optional[str] = None,
    ) -> None:
        """Record completed cycle and increment run counter."""
        now = datetime.now().isoformat()
        with self._lock:
            conn = self._get_connection()
            try:
                conn.execute(
                    """
                    UPDATE internal_agent_schedules
                    SET last_run_at = ?,
                        next_run_at = ?,
                        last_status = ?,
                        total_runs = total_runs + 1
                    WHERE agent_type = ?
                    """,
                    (now, next_run_at, status, agent_type),
                )
                conn.commit()
            finally:
                if self._memory_conn is None:
                    conn.close()
